function sortList(head) {
  if (head === null || head.next === null) return head;   // 0 or 1 nodes: sorted
  let slow = head, fast = head.next;                      // find the middle
  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
  }
  const right = slow.next;
  slow.next = null;                                       // cut the list in two
  return mergeLists(sortList(head), sortList(right));
}

function mergeLists(a, b) {
  const dummy = new ListNode(0);
  let tail = dummy;
  while (a !== null && b !== null) {
    if (a.val <= b.val) { tail.next = a; a = a.next; }
    else { tail.next = b; b = b.next; }
    tail = tail.next;
  }
  tail.next = a !== null ? a : b;                         // attach whatever is left
  return dummy.next;
}

def sort_list(head):
    if head is None or head.next is None:
        return head                       # 0 or 1 nodes: sorted
    slow, fast = head, head.next          # find the middle
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    right = slow.next
    slow.next = None                      # cut the list in two
    return merge_lists(sort_list(head), sort_list(right))


def merge_lists(a, b):
    dummy = tail = ListNode(0)
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a if a else b             # attach whatever is left
    return dummy.next

ListNode sortList(ListNode head) {
    if (head == null || head.next == null) return head;   // 0 or 1 nodes: sorted
    ListNode slow = head, fast = head.next;               // find the middle
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
    }
    ListNode right = slow.next;
    slow.next = null;                                     // cut the list in two
    return mergeLists(sortList(head), sortList(right));
}

ListNode mergeLists(ListNode a, ListNode b) {
    ListNode dummy = new ListNode(0), tail = dummy;
    while (a != null && b != null) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }
        else { tail.next = b; b = b.next; }
        tail = tail.next;
    }
    tail.next = a != null ? a : b;                        // attach whatever is left
    return dummy.next;
}

ListNode* mergeLists(ListNode* a, ListNode* b) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;                               // attach whatever is left
    return dummy.next;
}

